// Extrai { phone, message } do payload do seu provedor de WhatsApp.
// Cobre os formatos mais comuns (Evolution API, Z-API, WPPConnect) — ajuste se o seu for diferente.
const body = $input.item.json.body ?? $input.item.json;

let phone = '';
let message = '';

if (body.phone && body.text) {
  // Z-API
  phone = body.phone;
  message = (body.text && body.text.message) || body.text || '';
} else if (body.data && body.data.key && body.data.key.remoteJid) {
  // Evolution API
  phone = String(body.data.key.remoteJid).replace('@s.whatsapp.net', '');
  message = (body.data.message && (body.data.message.conversation || (body.data.message.extendedTextMessage && body.data.message.extendedTextMessage.text))) || '';
  // Evolution API também manda eco de mensagens enviadas por nós — ignora.
  if (body.data.key.fromMe) { message = ''; }
} else if (body.from && body.body) {
  // WPPConnect
  phone = String(body.from).replace('@c.us', '');
  message = body.body || '';
} else {
  // Formato não reconhecido — ajuste os campos abaixo pro seu provedor.
  phone = body.phone || body.from || '';
  message = body.message || body.text || body.body || '';
}

return [{ json: { phone: String(phone).replace(/\D/g, ''), message: String(message).trim() } }];
